1	-- =====================================================================
2	-- M3 — protect privileged provider columns. RLS lets a provider update their
3	-- own row, but row policies don't restrict columns; without this a provider
4	-- could self-approve (set status='approved') or fake their rating. This trigger
5	-- freezes those columns for ordinary authenticated users. Trusted server writes
6	-- (service role → auth.uid() is null) and admins pass through.
7	-- =====================================================================
8	
9	create or replace function public.guard_provider_privileged_columns()
10	returns trigger
11	language plpgsql
12	security definer
13	set search_path = public
14	as $$
15	begin
16	  if auth.uid() is null or public.is_admin() then
17	    return new;
18	  end if;
19	  -- Ordinary provider editing their own profile: keep these as-is.
20	  new.status            := old.status;
21	  new.bg_check_status   := old.bg_check_status;
22	  new.bg_check_ref      := old.bg_check_ref;
23	  new.payout_account_ref := old.payout_account_ref;
24	  new.rating_avg        := old.rating_avg;
25	  new.rating_count      := old.rating_count;
26	  return new;
27	end;
28	$$;
29	
30	create trigger providers_guard_privileged
31	  before update on public.providers
32	  for each row execute function public.guard_provider_privileged_columns();
33

1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { createClient } from "@/lib/supabase/server";
5	import { homeForRole } from "@/lib/auth";
6	import { signInSchema, signUpSchema } from "@/lib/validation/schemas";
7	import { t } from "@/lib/i18n";
8	import { type UserRole } from "@/lib/supabase/types";
9	
10	export interface AuthFormState {
11	  error?: string;
12	  fieldErrors?: Record<string, string>;
13	}
14	
15	function fieldErrorsFrom(
16	  issues: { path: (string | number)[]; message: string }[],
17	): Record<string, string> {
18	  const out: Record<string, string> = {};
19	  for (const issue of issues) {
20	    const key = String(issue.path[0] ?? "");
21	    if (key && !out[key]) out[key] = issue.message;
22	  }
23	  return out;
24	}
25	
26	export async function signUpAction(
27	  _prev: AuthFormState,
28	  formData: FormData,
29	): Promise<AuthFormState> {
30	  const parsed = signUpSchema.safeParse({
31	    fullName: formData.get("fullName"),
32	    email: formData.get("email"),
33	    password: formData.get("password"),
34	    role: formData.get("role"),
35	  });
36	
37	  if (!parsed.success) {
38	    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
39	  }
40	
41	  const { fullName, email, password, role } = parsed.data;
42	  const supabase = await createClient();
43	
44	  const { error } = await supabase.auth.signUp({
45	    email,
46	    password,
47	    options: {
48	      data: { role, full_name: fullName },
49	    },
50	  });
51	
52	  if (error) {
53	    if (
54	      error.message.toLowerCase().includes("already") ||
55	      error.code === "user_already_exists"
56	    ) {
57	      return { error: t("auth.errorEmailTaken") };
58	    }
59	    return { error: t("auth.errorGeneric") };
60	  }
61	
62	  // Email confirmation is disabled locally, so a session now exists.
63	  redirect(homeForRole(role));
64	}
65	
66	export async function signInAction(
67	  _prev: AuthFormState,
68	  formData: FormData,
69	): Promise<AuthFormState> {
70	  const parsed = signInSchema.safeParse({
71	    email: formData.get("email"),
72	    password: formData.get("password"),
73	  });
74	
75	  if (!parsed.success) {
76	    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
77	  }
78	
79	  const supabase = await createClient();
80	  const { error } = await supabase.auth.signInWithPassword(parsed.data);
81	
82	  if (error) {
83	    return { error: t("auth.errorInvalid") };
84	  }
85	
86	  const {
87	    data: { user },
88	  } = await supabase.auth.getUser();
89	  let role: UserRole = "customer";
90	  if (user) {
91	    const { data } = await supabase
92	      .from("profiles")
93	      .select("*")
94	      .eq("id", user.id)
95	      .maybeSingle();
96	    if (data?.role) role = data.role;
97	  }
98	
99	  const nextParam = formData.get("next");
100	  redirect(typeof nextParam === "string" && nextParam.startsWith("/")
101	    ? nextParam
102	    : homeForRole(role));
103	}
104	
105	export async function signOutAction(): Promise<void> {
106	  const supabase = await createClient();
107	  await supabase.auth.signOut();
108	  redirect("/signin");
109	}
