1	"use server";
2	
3	import { z } from "zod";
4	import { revalidatePath } from "next/cache";
5	import { requireRole } from "@/lib/auth";
6	import { createClient } from "@/lib/supabase/server";
7	import { getPayments } from "@/lib/integrations/payments";
8	import { cancellationOutcome } from "@/lib/pricing";
9	
10	const uuid = z.string().uuid();
11	
12	/** Save a listener to the customer's favorites (idempotent). */
13	export async function addFavorite(
14	  providerId: string,
15	): Promise<{ ok: boolean }> {
16	  const profile = await requireRole("customer");
17	  if (!uuid.safeParse(providerId).success) return { ok: false };
18	  const supabase = await createClient();
19	  const { error } = await supabase
20	    .from("favorites")
21	    .upsert(
22	      { customer_id: profile.id, provider_id: providerId },
23	      { onConflict: "customer_id,provider_id", ignoreDuplicates: true },
24	    );
25	  if (error) return { ok: false };
26	  revalidatePath("/account");
27	  return { ok: true };
28	}
29	
30	/** Remove a listener from the customer's favorites. */
31	export async function removeFavorite(
32	  providerId: string,
33	): Promise<{ ok: boolean }> {
34	  const profile = await requireRole("customer");
35	  const supabase = await createClient();
36	  const { error } = await supabase
37	    .from("favorites")
38	    .delete()
39	    .eq("customer_id", profile.id)
40	    .eq("provider_id", providerId);
41	  if (error) return { ok: false };
42	  revalidatePath("/account");
43	  return { ok: true };
44	}
45	
46	export interface CancelResult {
47	  ok: boolean;
48	  released?: boolean;
49	  error?: string;
50	}
51	
52	/**
53	 * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
54	 * cancelled ≥1h before its start releases the hold, otherwise the block is
55	 * charged. A "now" booking that was never joined releases (the customer never
56	 * talked — "you're in control, leave any time"). Capture/refund go through the
57	 * payments adapter.
58	 */
59	export async function cancelBooking(bookingId: string): Promise<CancelResult> {
60	  const profile = await requireRole("customer");
61	  if (!uuid.safeParse(bookingId).success) {
62	    return { ok: false, error: "Booking not found." };
63	  }
64	  const supabase = await createClient();
65	
66	  const { data: booking } = await supabase
67	    .from("bookings")
68	    .select("*")
69	    .eq("id", bookingId)
70	    .maybeSingle();
71	  if (!booking || booking.customer_id !== profile.id) {
72	    return { ok: false, error: "Booking not found." };
73	  }
74	  if (booking.status !== "confirmed") {
75	    return { ok: false, error: "This booking can't be cancelled." };
76	  }
77	
78	  let release: boolean;
79	  if (booking.start_mode === "scheduled") {
80	    release =
81	      cancellationOutcome({
82	        priceBlockCents: booking.price_block_cents,
83	        scheduledAt: booking.scheduled_at,
84	        nowMs: Date.now(),
85	      }).action === "release";
86	  } else {
87	    release = true; // a "now" booking that was never joined
88	  }
89	
90	  // Make the status transition the gate for the money side-effect: only the
91	  // call that actually flips confirmed → cancelled proceeds to refund/capture,
92	  // so a concurrent/retried cancel can't double-refund or double-capture.
93	  const { data: transitioned, error } = await supabase
94	    .from("bookings")
95	    .update({ status: "cancelled" })
96	    .eq("id", bookingId)
97	    .eq("customer_id", profile.id)
98	    .eq("status", "confirmed")
99	    .select("id");
100	  if (error) return { ok: false, error: "Could not cancel the booking." };
101	  if (!transitioned || transitioned.length === 0) {
102	    return { ok: false, error: "This booking can't be cancelled." };
103	  }
104	
105	  const payments = getPayments();
106	  if (booking.payment_ref) {
107	    if (release) {
108	      await payments.refund({
109	        paymentRef: booking.payment_ref,
110	        amountCents: booking.price_block_cents,
111	      });
112	    } else {
113	      await payments.capture({
114	        paymentRef: booking.payment_ref,
115	        amountCents: booking.price_block_cents,
116	      });
117	    }
118	  }
119	
120	  revalidatePath("/account");
121	  return { ok: true, released: release };
122	}
123	
124	const rescheduleSchema = z.object({
125	  bookingId: uuid,
126	  scheduledAt: z.string().datetime(),
127	});
128	
129	/** Move a confirmed booking to a new future time. */
130	export async function rescheduleBooking(input: {
131	  bookingId: string;
132	  scheduledAt: string;
133	}): Promise<{ ok: boolean; error?: string }> {
134	  const profile = await requireRole("customer");
135	  const parsed = rescheduleSchema.safeParse(input);
136	  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
137	  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
138	    return { ok: false, error: "Pick a time in the future." };
139	  }
140	
141	  const supabase = await createClient();
142	  const { error } = await supabase
143	    .from("bookings")
144	    .update({
145	      scheduled_at: parsed.data.scheduledAt,
146	      start_mode: "scheduled",
147	    })
148	    .eq("id", parsed.data.bookingId)
149	    .eq("customer_id", profile.id)
150	    .eq("status", "confirmed");
151	  if (error) return { ok: false, error: "Could not reschedule." };
152	
153	  revalidatePath("/account");
154	  return { ok: true };
155	}
156	
157	/** Update the customer's display name. */
158	export async function updateProfileName(
159	  name: string,
160	): Promise<{ ok: boolean; error?: string }> {
161	  const profile = await requireRole("customer");
162	  const trimmed = name.trim();
163	  if (trimmed.length < 1 || trimmed.length > 120) {
164	    return { ok: false, error: "Enter your name." };
165	  }
166	  const supabase = await createClient();
167	  const { error } = await supabase
168	    .from("profiles")
169	    .update({ full_name: trimmed })
170	    .eq("id", profile.id);
171	  if (error) return { ok: false, error: "Could not save your name." };
172	  revalidatePath("/account/settings");
173	  return { ok: true };
174	}
