76	const suspendSchema = z.object({
77	  userId: z.string().uuid(),
78	  suspended: z.boolean(),
79	});
80	
81	/**
82	 * Suspend or reinstate a user (admin only). Sets profiles.is_suspended; if the
83	 * user is a provider, also flips their provider status (suspended ⇄ approved)
84	 * so they leave / re-enter browse. Writes via the service-role client.
85	 */
86	export async function setUserSuspended(input: {
87	  userId: string;
88	  suspended: boolean;
89	}): Promise<{ ok: boolean }> {
90	  await requireRole("admin");
91	  const parsed = suspendSchema.safeParse(input);
92	  if (!parsed.success) return { ok: false };
93	  const { userId, suspended } = parsed.data;
94	
95	  const admin = createAdminClient();
96	  const { data: target } = await admin
97	    .from("profiles")
98	    .select("role")
99	    .eq("id", userId)
100	    .maybeSingle();
101	  if (!target) return { ok: false };
102	  // Admins are never suspendable — the UI hides the action; enforce it on the
103	  // server too so a crafted call can't put an admin into a suspended state.
104	  if (target.role === "admin") return { ok: false };
105	
106	  const { error } = await admin
107	    .from("profiles")
108	    .update({ is_suspended: suspended })
109	    .eq("id", userId);
110	  if (error) return { ok: false };
111	
112	  if (target.role === "provider") {
113	    // Only toggle the browse/approval gate for providers that are actually in
114	    // the approved⇄suspended pair. Never overwrite a pending/rejected status on
115	    // suspend (it would be lost), and never auto-approve a pending/rejected
116	    // provider on reinstate (that would bypass the M3/M4 vetting gate).
117	    const { data: prov } = await admin
118	      .from("providers")
119	      .select("status")
120	      .eq("id", userId)
121	      .maybeSingle();
122	    if (suspended && prov?.status === "approved") {
123	      await admin.from("providers").update({ status: "suspended" }).eq("id", userId);
124	    } else if (!suspended && prov?.status === "suspended") {
125	      await admin.from("providers").update({ status: "approved" }).eq("id", userId);
126	    }
127	  }
128	
129	  revalidatePath("/admin/users");
130	  revalidatePath("/admin/reports");
131	  return { ok: true };
132	}
