1	import "server-only";
2	import { createServerClient, type CookieOptions } from "@supabase/ssr";
3	import { cookies } from "next/headers";
4	import { type Database } from "@/lib/supabase/types";
5	import { supabaseAnonKey, supabaseUrl } from "@/lib/supabase/env";
6	
7	/**
8	 * Server Supabase client bound to the request cookies (anon key, RLS-enforced).
9	 * Use in Server Components, Server Actions, and Route Handlers.
10	 */
11	export async function createClient() {
12	  const cookieStore = await cookies();
13	
14	  return createServerClient<Database>(supabaseUrl(), supabaseAnonKey(), {
15	    cookies: {
16	      getAll() {
17	        return cookieStore.getAll();
18	      },
19	      setAll(
20	        cookiesToSet: { name: string; value: string; options?: CookieOptions }[],
21	      ) {
22	        try {
23	          for (const { name, value, options } of cookiesToSet) {
24	            cookieStore.set(name, value, options);
25	          }
26	        } catch {
27	          // `setAll` called from a Server Component — safe to ignore; the
28	          // middleware refreshes the session cookie on each request.
29	        }
30	      },
31	    },
32	  });
33	}
