34	 * /signin when signed out, or to the role's home when the role doesn't match.
35	 * Use at the top of protected Server Components and actions (CLAUDE.md rule 5).
36	 */
37	export async function requireRole(
38	  roles: UserRole | UserRole[],
39	): Promise<ProfileRow> {
